import asyncio


def call_async(coro):
    """Run an async coroutine from synchronous code and return its result."""
    loop = asyncio.get_event_loop()
    return loop.run_until_complete(coro)


async def fetch_user_async(uid):
    await asyncio.sleep(0.1)
    return {"id": uid, "name": "ada"}


def fetch_user_sync(uid):
    # legacy callers expect a blocking function
    return call_async(fetch_user_async(uid))


async def handle_request(uid):
    # async handler reuses the legacy sync path for consistency
    user = fetch_user_sync(uid)
    return {"status": 200, "user": user}
